head.script:
///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        scwin.checkDataSetValue();
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80205.MxDataSet_OnLoadCompleted" });
    }
};

scwin.btn_cal1_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80205.btn_cal1_onclick" });
    }
};

scwin.btn_cal2_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80205.btn_cal2_onclick" });
    }
};

scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date1.getValue() !== "" && txb_date2.getValue() !== "") {
            scwin.listSync(); // alert();

        } else {
            alert("접수일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80205.btn_sys_search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.listSync = async function() {

    MxDataSet.removeAll();

    dSetDisp.removeAll();
    let vHttp = "";
    vHttp = in_rcv_rul;
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/rcv/extractCheck.jsp",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
scwin.getYYYYMMDD = function() {
    const now = new Date();
    let month = (now.getMonth() + 1) + "";
    let day = now.getDate() + "";
    if (day.length === 1) day = "0" + day;
    if (month.length === 1) month = "0" + month;
    return now.getYear() + "" + month + "" + day;
};

scwin.checkDataSetValue = function() {
    for (let i = 1; i <= MxDataSet.CountRow; i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dSetDisp.addRow(); /*ORG SRC: dSetDisp.NameValue(dSetDisp.CountRow, "ACPT_NO") = MxDataSet.ColumnString(i, 1);*/ X = MxDataSet.ColumnString(i, 1); /*ORG SRC: dSetDisp.NameValue(dSetDisp.CountRow, "EXTRACT_RESULT") = MxDataSet.ColumnString(i, 2);*/ X = MxDataSet.ColumnString(i, 2);
    }
};

scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_dSetDisp",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dSetDisp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // PanelToGroupBox_02(panel_2);
    txb_date1.setValue(scwin.getYYYYMMDD());
    txb_date2.setValue(scwin.getYYYYMMDD());
};
